#[unsafe(no_mangle)]
pub unsafe extern "C" fn GetEggCyclesToSubtract() -> u8_0 {
    let mut count: u8_0 = 0;
    let mut i: u8_0 = 0;
    count = CalculatePlayerPartyCount();
    i = 0 as u8_0;
    while (i as ::core::ffi::c_int) < count as ::core::ffi::c_int {
        if GetMonData2(
            (&raw mut gPlayerParty as *mut Pokemon).offset(i as isize) as *mut Pokemon,
            MON_DATA_SANITY_IS_EGG as ::core::ffi::c_int as s32,
        ) == 0
        {
            let mut ability: u8_0 = GetMonAbility(
                (&raw mut gPlayerParty as *mut Pokemon).offset(i as isize)
                    as *mut Pokemon,
            );
            if ability as ::core::ffi::c_int == 40 as ::core::ffi::c_int
                || ability as ::core::ffi::c_int == 49 as ::core::ffi::c_int
            {
                return 2 as u8_0;
            }
        }
        i = i.wrapping_add(1);
    }
    return 1 as u8_0;
}
